"""Per-request USD accounting, separate from model-visible evidence and SDK estimates."""
from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal
import math
from threading import Lock


@dataclass(frozen=True)
class CostItem:
    provider: str
    operation: str
    model: str | None = None
    mode: str | None = None
    requests: int = 1
    amount_usd: float | None = None
    estimated_usd: float | None = None
    source: str = "unknown"
    usage: tuple[tuple[str, int], ...] = ()


@dataclass(frozen=True)
class Costs:
    currency: str = "USD"
    items: tuple[CostItem, ...] = ()
    total_usd: float | None = None
    known_total_usd: float = 0.0
    estimated_total_usd: float | None = None
    complete: bool = False


def amount(value) -> float | None:
    if type(value) not in (int, float) or not math.isfinite(value) or value < 0:
        return None
    return float(value)


def _sum(values) -> float:
    return float(sum((Decimal(str(value)) for value in values), Decimal(0)))


def summarize(items) -> Costs:
    grouped = {}
    for item in items:
        key = (item.provider, item.operation, item.model, item.mode, item.source)
        grouped.setdefault(key, []).append(item)
    rows = []
    for group in grouped.values():
        first = group[0]
        usage = {}
        for item in group:
            for name, count in item.usage:
                usage[name] = usage.get(name, 0) + count
        # A missing amount must never turn into a zero or a partial 'total'.
        actual = _sum(i.amount_usd for i in group) if all(i.amount_usd is not None for i in group) else None
        estimate = _sum(i.estimated_usd for i in group) if all(i.estimated_usd is not None for i in group) else None
        rows.append(CostItem(first.provider, first.operation, first.model, first.mode,
                             sum(i.requests for i in group), actual, estimate, first.source,
                             tuple(sorted(usage.items()))))
    known = _sum(i.amount_usd for i in rows if i.amount_usd is not None)
    complete = all(i.amount_usd is not None for i in rows)
    estimated = [i.amount_usd if i.amount_usd is not None else i.estimated_usd for i in rows]
    return Costs(items=tuple(rows), total_usd=known if complete else None, known_total_usd=known,
                 estimated_total_usd=_sum(estimated) if all(v is not None for v in estimated) else None,
                 complete=complete)


def model_items(messages, provider: str, model: str):
    """Only pass messages generated by this invocation, never the supplied history.

    Normalized usage.cost is a price-catalog estimate, not a charge returned by DeepSeek.
    Custom backends may explicitly report usage.cost_usd as an actual USD charge.
    """
    for message in messages:
        if message.get("role") != "assistant":
            continue
        usage = message.get("usage")
        usage = usage if isinstance(usage, dict) else {}
        actual = amount(usage.get("cost_usd"))
        cost = usage.get("cost")
        estimate = amount(cost.get("total")) if isinstance(cost, dict) else None
        # SDKs initialize missing usage to all-zero values; this is not proof of free usage.
        if not any(type(usage.get(k)) is int and usage[k] > 0 for k in ("input", "output", "totalTokens", "cacheRead", "cacheWrite")):
            estimate = None
        counts = tuple((k, usage[k]) for k in ("input", "output", "cacheRead", "cacheWrite", "reasoning", "totalTokens")
                       if type(usage.get(k)) is int and usage[k] >= 0)
        yield CostItem(provider, "model", model=model, amount_usd=actual, estimated_usd=estimate,
                       source="provider_reported" if actual is not None else "sdk_catalog_estimate" if estimate is not None else "unknown",
                       usage=counts)


class ToolCosts:
    """No queries, URLs, response bodies or credentials are retained here."""

    def __init__(self):
        self._items: list[CostItem] = []
        self._lock = Lock()

    def record(self, provider: str, operation: str, payload: dict | None, *, mode=None, free=False):
        counts = {}
        payload = payload if isinstance(payload, dict) else {}
        usage = payload.get("usage")
        if provider == "parallel" and isinstance(usage, list):
            for row in usage:
                if (isinstance(row, dict) and isinstance(row.get("name"), str)
                        and len(row["name"]) <= 100 and type(row.get("count")) is int and row["count"] >= 0):
                    counts[row["name"]] = counts.get(row["name"], 0) + row["count"]
        elif provider == "jina":
            data = payload.get("data")
            usage = usage if isinstance(usage, dict) else data.get("usage", {}) if isinstance(data, dict) else {}
            if isinstance(usage, dict):
                counts = {k: usage[k] for k in ("tokens", "total_tokens") if type(usage.get(k)) is int and usage[k] >= 0}
        # Neither current Search schema reports dollars. Tokens/SKU counts are not USD.
        item = CostItem(provider, operation, mode=mode, amount_usd=0.0 if free else None,
                        source=("no_api_fee" if provider == "ddgs" else "anonymous_free_tier") if free else "unknown",
                        usage=tuple(sorted(counts.items())))
        with self._lock:
            self._items.append(item)

    def snapshot(self) -> tuple[CostItem, ...]:
        with self._lock:
            return tuple(self._items)

    def clear(self):
        with self._lock:
            self._items.clear()
